28	public record StreamableGroupBy<K, T>(Streamable<T> source, Function<? super T, ? extends K> keySelector)
29	implements Streamable<GroupedStreamable<K, T>>, HasUpstreamStreamableSource<T> {
30	
31	    @Override
32	    public @NonNull Streamer<GroupedStreamable<K, T>> stream(@NonNull StreamerCancellation cancellation) {
33	        var streamer = new GroupByStreamer<K, T>(source.stream(cancellation), keySelector);
34	        streamer.drain();
35	        return streamer;
36	    }
37	
38	    static final class GroupByStreamer<K, T>
39	    implements Streamer<GroupedStreamable<K, T>>,
40	    BiConsumer<Object, Throwable>, java.util.function.Function<Boolean, Boolean> {
41	
42	        final Streamer<T> upstream;
43	
44	        final Function<? super T, ? extends K> keySelector;
45	
46	        final AtomicInteger wip;
47	
48	        final Map<K, BasicGroupedStreamable<K, T>> groups;
49	
50	        final CompletableFuture<Void> onFinish;
51	
52	        volatile boolean done;
53	
54	        volatile GroupedStreamable<K, T> currentGroup;
55	
56	        volatile GroupedStreamable<K, T> currentNext;
57	
58	        final StageResumable<Boolean> mainNext;
59	
60	        GroupByStreamer(Streamer<T> upstream, Function<? super T, ? extends K> keySelector) {
61	            this.upstream = upstream;
62	            this.keySelector = keySelector;
63	            this.wip = new AtomicInteger();
64	            this.groups = new ConcurrentHashMap<>();
65	            this.mainNext = new StageResumable<>();
66	            this.onFinish = new CompletableFuture<>();
67	        }
68	
69	        @Override
70	        public @NonNull CompletionStage<Boolean> next() {
71	            var cs = mainNext.await().thenApply(this);
72	            return cs;
73	        }
74	
75	        @Override
76	        public Boolean apply(Boolean v) {
77	            if (v) {
78	                currentNext = currentGroup;
79	            } else {
80	                currentNext = null;
81	            }
82	            currentGroup = null;
83	            return v;
84	        }
85	
86	        @Override
87	        public @NonNull GroupedStreamable<K, T> current() {
88	            return currentNext;
89	        }
90	
91	        @Override
92	        public @NonNull CompletionStage<Void> finish() {
93	            done = true;
94	            drain();
95	            return onFinish;
96	        }
97	
98	        void drain() {
99	            if (wip.getAndIncrement() != 0) {
100	                return;
101	            }
102	
103	            do {
104	                if (done) {
105	                    upstream.finish().whenComplete(this);
106	                    break;
107	                } else {
108	                    upstream.next().whenComplete(this);
109	                }
110	            } while (wip.decrementAndGet() != 0);
111	        }
112	
113	        @Override
114	        public void accept(Object t, Throwable u) {
115	            if (done) {
116	                upstream.finish().whenComplete((v, e) -> {
117	                    currentNext = null;
118	                    currentGroup = null;
119	                    if (e != null) {
120	                        onFinish.completeExceptionally(e);
121	                    } else {
122	                        onFinish.complete(v);
123	                    }
124	                });
125	            } else {
126	                if (u != null) {
127	                    done = true;
128	                    for (var g : groups.values()) {
129	                        g.finish(u); // TODO whenComplete
130	                    }
131	                    groups.clear();
132	                    mainNext.ready().completeExceptionally(u);
133	                } else
134	                if ((Boolean)t) {
135	                    try {
136	                        var c = upstream.current();
137	                        var key = keySelector.apply(c);
138	
139	                        var g = groups.get(key);
140	                        if (g == null) {
141	                            g = new AsyncGroup<>(key, this);
142	                            groups.put(key, g);
143	                            currentGroup = g;
144	                            mainNext.ready().complete(true);
145	                        }
146	                        g.next(c).whenComplete((_, _) -> drain());
147	                    } catch (Throwable ex) {
148	                        Exceptions.throwIfFatal(ex);
149	                        done = true;
150	                        for (var g : groups.values()) {
151	                            g.finish(ex);
152	                        }
153	                        groups.clear();
154	                        mainNext.ready().completeExceptionally(ex);
155	                    }
156	                } else {
157	                    done = true;
158	                    for (var g : groups.values()) {
159	                        g.finish(null);
160	                    }
161	                    groups.clear();
162	                    mainNext.ready().complete(false);
163	                }
164	            }
165	        }
166	
167	        @SuppressWarnings("unchecked")
168	        void delete(K key) {
169	            groups.replace(key, (BasicGroupedStreamable<K, T>)TombstoneGroup.INSTANCE);
170	        }
171	
172	        boolean isDeleted(K key) {
173	            var e = groups.get(key);
174	            return e == null || e == TombstoneGroup.INSTANCE;
175	        }
176	    }
177	
178	    static abstract class BasicGroupedStreamable<K, T> extends GroupedStreamable<K, T>
179	    implements StreamSink<T> {
180	        BasicGroupedStreamable(K key) {
181	            super(key);
182	        }
183	
184	        public abstract CompletionStage<Boolean> next(@NonNull T value);
185	
186	        public abstract CompletionStage<Void> finish(@Nullable Throwable throwable);
187	    }
188	
189	    static final class AsyncGroup<K, T> extends BasicGroupedStreamable<K, T>
190	    implements Streamer<T>, Disposable, java.util.function.Function<Boolean, Boolean> {
191	
192	        final AtomicBoolean once;
193	
194	        final GroupByStreamer<K, T> parent;
195	
196	        final StageResumable<Boolean> sendCanProgress;
197	
198	        final StageResumable<Boolean> nextCanProgress;
199	
200	        volatile T item;
201	
202	        volatile T current;
203	
204	        StreamerCancellation cancellation;
205	
206	        AsyncGroup(K key, GroupByStreamer<K, T> parent) {
207	            super(key);
208	            this.once = new AtomicBoolean();
209	            this.parent = parent;
210	            this.sendCanProgress = new StageResumable<>();
211	            this.nextCanProgress = new StageResumable<>();
212	        }
213	
214	        @Override
215	        public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
216	            if (once.compareAndSet(false, true)) {
217	                this.cancellation = cancellation;
218	                cancellation.add(this);
219	                return this;
220	            }
221	            return StreamableError.createFailed(new IllegalStateException("Only one streamer is allowed!"));
222	        }
223	
224	        @Override
225	        public CompletionStage<Boolean> next(T value) {
226	            return sendCanProgress.await().thenApply(_ -> {
227	                item = value;
228	                nextCanProgress.ready().complete(true);
229	                return true;
230	            });
231	        }
232	
233	        @Override
234	        public CompletionStage<Void> finish(@Nullable Throwable throwable) {
235	            return sendCanProgress.await().thenAccept(_ -> {
236	                if (throwable == null) {
237	                    nextCanProgress.ready().complete(false);
238	                } else {
239	                    nextCanProgress.ready().completeExceptionally(throwable);
240	                }
241	            });
242	        }
243	
244	        @Override
245	        public @NonNull CompletionStage<Boolean> next() {
246	            sendCanProgress.ready().complete(true);
247	            return nextCanProgress.await().thenApply(this);
248	        }
249	
250	        @Override
251	        public @NonNull Boolean apply(@NonNull Boolean b) {
252	            current = item;
253	            item = null;
254	            return b;
255	        }
256	
257	        @Override
258	        public @NonNull T current() {
259	            return current;
260	        }
261	
262	        @Override
263	        public @NonNull CompletionStage<Void> finish() {
264	            this.cancellation.remove(this);
265	            return FINISHED;
266	        }
267	
268	        @Override
269	        public void dispose() {
270	            parent.delete(getKey());
271	        }
272	
273	        @Override
274	        public boolean isDisposed() {
275	            return parent.isDeleted(getKey());
276	        }
277	    }
278	
279	    static final class TombstoneGroup extends BasicGroupedStreamable<Object, Object> {
280	
281	        static final Object TOMBSTONE_KEY = new Object();
282	
283	        static final TombstoneGroup INSTANCE = new TombstoneGroup();
284	
285	        TombstoneGroup() {
286	            super(TOMBSTONE_KEY);
287	        }
288	
289	        @Override
290	        public @NonNull Streamer<@NonNull Object> stream(@NonNull StreamerCancellation cancellation) {
291	            return StreamableError.createFailed(new CancellationException("TOMBSTONE"));
292	        }
293	
294	        @Override
295	        public CompletionStage<Boolean> next(Object value) {
296	            return Streamer.NEXT_TRUE;
297	        }
298	
299	        @Override
300	        public CompletionStage<Void> finish(@Nullable Throwable throwable) {
301	            return Streamer.FINISHED;
302	        }
303	    }
304	}
