30	public record StreamableTakeUntil<T, U>(
31	        Streamable<T> source,
32	        Streamable<U> other
33	) implements Streamable<T>, HasUpstreamStreamableSource<T> {
34	
35	    @Override
36	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
37	        var otherCancellation = cancellation.derive();
38	        var otherStreamer = other.stream(otherCancellation);
39	        var mainCancellation = cancellation.derive();
40	        var mainStreamer = source.stream(mainCancellation);
41	
42	        var streamer = new TakeUntilMainStreamer<>(
43	                mainStreamer, otherStreamer, mainCancellation, otherCancellation,
44	                suppressValueAndCancel(otherStreamer.next(), false)
45	            );
46	
47	        return streamer;
48	    }
49	
50	    static final class TakeUntilMainStreamer<T, U> implements Streamer<T> {
51	
52	        final Streamer<? extends T> upstream;
53	
54	        final Streamer<? extends U> otherStreamer;
55	
56	        final DisposableStreamerCancellation mainCancellation;
57	
58	        final DisposableStreamerCancellation otherCancellation;
59	
60	        final CompletionStage<Boolean> otherNext;
61	
62	        CompletionStage<Boolean> mainNext;
63	
64	        public TakeUntilMainStreamer(
65	                Streamer<? extends T> upstream,
66	                Streamer<? extends U> otherStreamer,
67	                DisposableStreamerCancellation mainCancellation,
68	                DisposableStreamerCancellation otherCancellation,
69	                CompletionStage<Boolean> otherNext
70	        ) {
71	            this.upstream = upstream;
72	            this.otherStreamer = otherStreamer;
73	            this.mainCancellation = mainCancellation;
74	            this.otherCancellation = otherCancellation;
75	            this.otherNext = otherNext;
76	        }
77	
78	        @Override
79	        public @NonNull CompletionStage<Boolean> next() {
80	            mainNext = suppressCancel(upstream.next(), mainCancellation, false);
81	            return StreamableHelper.race(mainNext, otherNext, w -> {
82	                if (w == 2) {
83	                    mainCancellation.dispose();
84	                }
85	            });
86	        }
87	
88	        @Override
89	        public @NonNull T current() {
90	            return upstream.current();
91	        }
92	
93	        @Override
94	        public @NonNull CompletionStage<Void> finish() {
95	            otherCancellation.dispose();
96	            return andThenSupply(
97	                    whenBoth(mainNext, otherNext),
98	                    () -> whenBoth(upstream.finish(), otherStreamer.finish())
99	                   );
100	        }
101	    }
102	}
